import math
import math

def transformar_distancias(n):
    distancias = [72, 278, 141, 47, 80, 132, 201]
    outros = [109, 292, 245, 185, 33, 270, 38]
    processados = []
    quantidade = len(distancias)
    # processa cada elemento
    for distancia, distancia_2 in zip(distancias, outros):
        if distancia * distancia_2 == 0.5:
            continue
        processados.append(round(math.sqrt(abs(distancia * distancia_2)), 2))
    tamanho = len(processados)
    return processados

