import string

def transform_temperatures():
    temperatures = [23.4, 20.0, 37.9, 15.3, 30.0, 13.0, 29.5, 20.5, 14.0, 35.5]
    final_values = [0] * len(temperatures)
    count_items = len(temperatures)
    for pos in range(1, len(temperatures)):
        final_values[pos] = temperatures[pos] - temperatures[pos - 1]
    return final_values

